class TabularAndSpatialFormatsIT {
    static org.neo4j.driver.Driver driver;
    static final Path ROOT=TestInstallationPaths.runRoot();
    String token,namespace;
    static Map<String,Object> m(Object... entries){return TestTransport.orderedMap(entries);}
    static org.neo4j.driver.Record call(String procedure,Object... args){var call=TestTransport.positionalCall(procedure,args);try(var session=driver.session()){return session.run("CYPHER 25 "+call.text(),call.parameters()).list().getFirst();}}
    static String id(org.neo4j.driver.Record row){return row.get("node").asNode().get("id").asString();}
    static String hash(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception e){throw new AssertionError(e);}}
    static String upload(byte[] bytes,String filename,String token){String checksum=hash(bytes);String upload=call("deposit.resource.beginUpload",filename,(long)bytes.length,checksum,"text/csv; charset=utf-8",token).get("data").get("uploadId").asString();if(bytes.length>0)call("deposit.resource.uploadChunk",upload,0L,Base64.getEncoder().encodeToString(bytes),checksum,token);return call("deposit.resource.finishUpload",upload,token).get("data").get("resourceId").asString();}
    static Map<String,Object> context(String token){return m("token",token,"requestId",UUID.randomUUID().toString());}
    void releaseAction(String actorToken){call("deposit.action.release",actorToken);}
    static String failureSignature(org.neo4j.driver.exceptions.ClientException failure){var code=Pattern.compile("\\\"code\\\":\\\"([^\\\"]+)\\\"").matcher(failure.getMessage());var message=Pattern.compile("\\\"message\\\":\\\"([^\\\"]*)\\\"").matcher(failure.getMessage());assertTrue(code.find(),failure.getMessage());assertTrue(message.find(),failure.getMessage());return code.group(1)+"|"+message.group(1);}
    long namespaceRevision(){try(var session=driver.session()){return session.run("MATCH (n:Namespace {id:$id}) RETURN n.sequence AS revision",m("id",namespace)).single().get("revision").asLong();}}
    long namespaceHistoryCount(){try(var session=driver.session()){return session.run("MATCH (r:Revision {namespaceId:$id}) RETURN count(r) AS count",m("id",namespace)).single().get("count").asLong();}}
    List<Long> operationalState(){try(var session=driver.session()){return List.of(session.run("MATCH (n:Namespace {id:$id}) RETURN n.sequence AS n",m("id",namespace)).single().get("n").asLong(),session.run("MATCH (t:DepositTransfer {namespaceId:$id}) RETURN count(t) AS n",m("id",namespace)).single().get("n").asLong(),session.run("MATCH (t:DepositTabularTable {namespaceId:$id}) RETURN count(t) AS n",m("id",namespace)).single().get("n").asLong(),session.run("MATCH (r:DepositReceipt {scope:$id}) RETURN count(r) AS n",m("id",namespace)).single().get("n").asLong());}}
    Set<String> stagingFiles()throws Exception{Path staging=ROOT.resolve("resources/staging");if(!Files.exists(staging))return Set.of();try(var paths=Files.walk(staging)){return paths.filter(Files::isRegularFile).map(p->staging.relativize(p).toString()).collect(java.util.stream.Collectors.toSet());}}
    String transactionFailure(Transaction tx,String procedure,Map<String,Object> request){String query;Map<String,Object> params;if(procedure.equals("deposit.resource.beginUpload")){query="CYPHER 25 CALL deposit.resource.beginUpload($filename,$bytes,$sha256,$mediaType,$token)";params=m("filename",request.get("filename"),"bytes",request.get("bytes"),"sha256",request.get("sha256"),"mediaType",request.get("mediaType"),"token",token);}else{query="CYPHER 25 CALL deposit.load.csv($resourceId,$formatOptions,$token)";params=m("resourceId",request.get("resourceId"),"formatOptions",request.get("formatOptions"),"token",token);}var failure=assertThrows(org.neo4j.driver.exceptions.ClientException.class,()->tx.run(query,params).consume());return failureSignature(failure);}
    String afterPriorMutation(String procedure,Map<String,Object> request)throws Exception{try(var session=driver.session();var tx=session.beginTransaction()){tx.run("CYPHER 25 CALL deposit.create.class($name,$properties,$token)",m("name","OperationalPrecondition-"+UUID.randomUUID(),"properties",m(),"token",token)).consume();return transactionFailure(tx,procedure,request);}}
    String afterPriorSelection(String procedure,Map<String,Object> request){try(var session=driver.session();var tx=session.beginTransaction()){tx.run("CYPHER 25 CALL deposit.set.activeNamespace($namespace,$token)",m("namespace",m("id",namespace),"token",token)).consume();return transactionFailure(tx,procedure,request);}}
    org.neo4j.driver.Record assertNamespaceLockRefreshesRevision(String procedure,Map<String,Object> request,String editorToken)throws Exception{long before=namespaceRevision();var mutation=context(editorToken);mutation.put("operationId",UUID.randomUUID().toString());mutation.put("expectedRevision",before);var operation=context(token);operation.put("operationId",UUID.randomUUID().toString());var entered=new CountDownLatch(1);var executor=Executors.newSingleThreadExecutor();try(var session=driver.session();var transaction=session.beginTransaction()){transaction.run("CYPHER 25 CALL deposit.create.class($request,$context)",m("request",m("name","RevisionLock-"+UUID.randomUUID()),"context",mutation)).consume();var pending=executor.submit(()->{try(var requestSession=driver.session()){var params=m("p0",request,"p1",operation);entered.countDown();return requestSession.run("CYPHER 25 CALL "+procedure+"($p0,$p1)",params).list().getFirst();}});assertTrue(entered.await(2,TimeUnit.SECONDS));assertThrows(TimeoutException.class,()->pending.get(1,TimeUnit.SECONDS),"Operational action must wait for the Namespace coordination lock");transaction.commit();long after=namespaceRevision();assertTrue(after>before,"Preceding mutation must advance the Namespace revision");long historyBefore=namespaceHistoryCount();var result=pending.get(15,TimeUnit.SECONDS);assertEquals(after,result.get("meta").get("revision").asLong(),"Operational action must read revision after acquiring its Namespace lock");assertEquals(after,namespaceRevision(),"Operational writes must not advance the Namespace scientific revision");assertEquals(historyBefore,namespaceHistoryCount(),"Operational writes must not publish scientific history");String operationId=result.get("meta").get("operationId").asString();try(var receiptSession=driver.session()){var receipt=receiptSession.run("MATCH (r:DepositReceipt {scope:$scope,operationId:$operation}) RETURN r.revision AS revision",m("scope",namespace,"operation",operationId)).single();assertEquals(after,receipt.get("revision").asLong(),"Persisted receipt must capture the revision read after lock acquisition");}return result;}finally{executor.shutdownNow();}}
    static List<List<String>> parseCsvIndependently(String text){var rows=new ArrayList<List<String>>();var row=new ArrayList<String>();var field=new StringBuilder();boolean quoted=false;for(int i=0;i<text.length();i++){char ch=text.charAt(i);if(quoted){if(ch=='"'){if(i+1<text.length()&&text.charAt(i+1)=='"'){field.append('"');i++;}else quoted=false;}else field.append(ch);}else if(ch=='"'){assertEquals(0,field.length(),"CSV quote must begin a field");quoted=true;}else if(ch==','){row.add(field.toString());field.setLength(0);}else if(ch=='\r'){assertFalse(quoted);assertTrue(i+1<text.length()&&text.charAt(i+1)=='\n');i++;row.add(field.toString());field.setLength(0);rows.add(List.copyOf(row));row.clear();}else if(ch=='\n')fail("CSV records must use CRLF");else field.append(ch);}assertFalse(quoted,"Unclosed CSV quote");if(field.length()>0||!row.isEmpty()){row.add(field.toString());rows.add(List.copyOf(row));}return rows;}
    static byte[] download(String resource,long bytes,String token){var output=new java.io.ByteArrayOutputStream();for(long offset=0;offset<bytes;){long length=Math.min(1_048_576L,bytes-offset);var chunk=call("deposit.resource.downloadChunk",resource,offset,length,token).get("data");byte[] part=Base64.getDecoder().decode(chunk.get("bytesBase64").asString());assertEquals(length,part.length);output.writeBytes(part);offset+=length;}return output.toByteArray();}
    @BeforeAll static void connect()throws Exception{driver=CorpusTransport.wrap(GraphDatabase.driver(System.getenv("DEPOSIT_TEST_URI"),AuthTokens.basic("neo4j",System.getenv("DEPOSIT_TEST_PASSWORD"))));driver.verifyConnectivity();TestTransport.bootstrapIfFresh(driver,Duration.ofSeconds(30),"typed-data-admin","typed-data-account-password");}
    @AfterAll static void close(){if(driver!=null)driver.close();}
    @BeforeEach void setup(){token=call("deposit.utils.login","typed-data-admin","typed-data-account-password").get("value").asString();namespace=id(call("deposit.create.namespace","ImportExport-Formats-"+UUID.randomUUID(),m("historyMode","disabled"),token));call("deposit.set.activeNamespace",m("id",namespace),token);}

    @Test void resourceAndTabularOperationalPreconditionsMatchBeforeMutationAndLocks()throws Exception{
        String resourceProcedure="deposit.resource.beginUpload",tabularProcedure="deposit.load.csv";
        Map<String,Object> invalidResource=m("filename","invalid.txt","bytes",-1L,"sha256","0".repeat(64),"mediaType","text/plain"),invalidTabular=m("resourceId","not-a-uuid","formatOptions",m());
        var before=operationalState();var filesBefore=stagingFiles();
        var validResourceBodyFailure=assertThrows(org.neo4j.driver.exceptions.ClientException.class,()->call(resourceProcedure,invalidResource,contextWithOperation(token)));releaseAction(token);
        var validTabularBodyFailure=assertThrows(org.neo4j.driver.exceptions.ClientException.class,()->call(tabularProcedure,invalidTabular,contextWithOperation(token)));releaseAction(token);
        assertEquals("LIMIT_EXCEEDED|Upload size exceeds limit",failureSignature(validResourceBodyFailure));
        assertEquals("VALIDATION_FAILED|Invalid UUID",failureSignature(validTabularBodyFailure));

        String publicMutationFailure="VALIDATION_FAILED|Only one mutation is allowed per transaction; use batch";
        assertEquals(publicMutationFailure,afterPriorMutation(resourceProcedure,invalidResource));
        assertEquals(publicMutationFailure,afterPriorMutation(tabularProcedure,invalidTabular));

        String selectionFailure="VALIDATION_FAILED|Selection and scoped work need separate transactions";
        assertEquals(selectionFailure,afterPriorSelection(resourceProcedure,invalidResource));
        assertEquals(selectionFailure,afterPriorSelection(tabularProcedure,invalidTabular));
        assertEquals(before,operationalState(),"Rejected operational contexts must not advance revision or publish transfer/table/receipt nodes");assertEquals(filesBefore,stagingFiles(),"Rejected operational contexts must not create staging files");
    }

    Map<String,Object> contextWithOperation(String actorToken){var c=context(actorToken);c.put("operationId",UUID.randomUUID().toString());return c;}

    @Test void resourceAndTabularReadNamespaceRevisionAfterAcquiringOperationalLock()throws Exception{
        String username="operational-lock-editor-"+UUID.randomUUID();String user=call("deposit.create.user",username,"typed-data-account-password",m(),token).get("data").get("id").asString();
        call("deposit.set.namespaceRole",m("id",user),"editor",token);String editor=call("deposit.utils.login",username,"typed-data-account-password").get("value").asString();
        call("deposit.set.activeNamespace",m("id",namespace),editor);
        Map<String,Object> resourceRequest=ResourceAndGeometryIT.meta(new byte[0],"lock-order.txt");
        assertNamespaceLockRefreshesRevision("deposit.resource.beginUpload",resourceRequest,editor);
        call("deposit.action.release",token);
        String csv=upload("code\r\nLOCK-ORDER\r\n".getBytes(java.nio.charset.StandardCharsets.UTF_8),"lock-order.csv",token);
        assertNamespaceLockRefreshesRevision("deposit.load.csv",m("resourceId",csv,"formatOptions",m()),editor);
    }

    @Test void csvAndXlsxPreserveDifficultTypedValuesAndChecksums()throws Exception{
        var declarations=new ArrayList<Map<String,Object>>();for(var entry:m("LargeInteger","Integer","DifficultFloat","Float","Date","Date","Time","Time","DateTime","DateTime","LocalTime","LocalTime","LocalDateTime","LocalDateTime","Duration","Duration","Nested","List","Dictionary","DDict").entrySet())declarations.add(m("name",entry.getKey(),"type",entry.getValue()));
        call("deposit.create.class","Formats",m("descriptors",declarations),token);
        var values=m("LargeInteger",9_007_199_254_740_993L,"DifficultFloat",0.10000000000000002,"Date","2024-02-29","Time","12:34:56.123456789+02:00","DateTime","2024-06-01T12:34:56.123456789+02:00[Europe/Bratislava]","LocalTime","12:34:56.123456789","LocalDateTime","2024-06-01T12:34:56.123456789","Duration",m("months",14L,"days",-3L,"seconds",-4L,"nanoseconds",5L),"Nested",m("itemType","List","items",List.of(m("itemType","Integer","items",Arrays.asList(Long.MIN_VALUE,null,Long.MAX_VALUE)),m("itemType","String","items",List.of("comma,quote\"")))),"Dictionary",m("count",m("type","Integer","value",Long.MAX_VALUE),"nested",m("type","List","value",m("itemType","String","items",List.of("a","b")))));
        call("deposit.create.object","Formats",m("descriptors",values),token);
        String query="SELECT Formats.LargeInteger AS integer,Formats.DifficultFloat AS difficultFloat,Formats.Date AS date,Formats.Time AS time,Formats.DateTime AS dateTime,Formats.LocalTime AS localTime,Formats.LocalDateTime AS localDateTime,Formats.Duration AS duration,Formats.Nested AS nested,Formats.Dictionary AS dictionary";
        var csv=call("deposit.save.csv",m("query",query),m(),m("filename","typed.csv"),token).get("data");assertEquals("typed.csv",csv.get("filename").asString());byte[] csvBytes=download(csv.get("resourceId").asString(),csv.get("bytes").asLong(),token);assertEquals(csv.get("checksum").asString(),hash(csvBytes));String csvText=new String(csvBytes,java.nio.charset.StandardCharsets.UTF_8);var records=parseCsvIndependently(csvText);assertEquals(2,records.size());assertEquals(List.of("integer","difficultFloat","date","time","dateTime","localTime","localDateTime","duration","nested","dictionary"),records.get(0));var row=records.get(1);assertEquals(List.of("9007199254740993","0.10000000000000002","2024-02-29","12:34:56.123456789+02:00","2024-06-01T12:34:56.123456789+02:00[Europe/Bratislava]","12:34:56.123456789","2024-06-01T12:34:56.123456789","P1Y2M-3DT-3.999999995S"),row.subList(0,8));var json=new com.fasterxml.jackson.databind.ObjectMapper();assertEquals(json.readTree("{\"itemType\":\"List\",\"items\":[{\"itemType\":\"Integer\",\"items\":[\"-9223372036854775808\",null,\"9223372036854775807\"]},{\"itemType\":\"String\",\"items\":[\"comma,quote\\\"\"]}]}") ,json.readTree(row.get(8)));assertEquals(json.readTree("{\"count\":{\"type\":\"Integer\",\"value\":\"9223372036854775807\"},\"nested\":{\"type\":\"List\",\"value\":{\"itemType\":\"String\",\"items\":[\"a\",\"b\"]}}}") ,json.readTree(row.get(9)));
        var xlsx=call("deposit.save.xlsx",m("query",query),m(),m("filename","typed.xlsx","sheet","Typed values"),token).get("data");assertEquals("typed.xlsx",xlsx.get("filename").asString());byte[] xlsxBytes=download(xlsx.get("resourceId").asString(),xlsx.get("bytes").asLong(),token);assertEquals(xlsx.get("checksum").asString(),hash(xlsxBytes));try(Workbook workbook=WorkbookFactory.create(new ByteArrayInputStream(xlsxBytes))){Row workbookRow=workbook.getSheet("Typed values").getRow(1);assertEquals(CellType.STRING,workbookRow.getCell(0).getCellType());assertEquals("9007199254740993",workbookRow.getCell(0).getStringCellValue());assertEquals(CellType.STRING,workbookRow.getCell(1).getCellType());assertEquals(Double.toString(0.10000000000000002),workbookRow.getCell(1).getStringCellValue());assertEquals("2024-02-29",workbookRow.getCell(2).getStringCellValue());assertEquals("12:34:56.123456789+02:00",workbookRow.getCell(3).getStringCellValue());assertEquals("2024-06-01T12:34:56.123456789+02:00[Europe/Bratislava]",workbookRow.getCell(4).getStringCellValue());assertEquals("12:34:56.123456789",workbookRow.getCell(5).getStringCellValue());assertEquals("2024-06-01T12:34:56.123456789",workbookRow.getCell(6).getStringCellValue());assertEquals("P1Y2M-3DT-3.999999995S",workbookRow.getCell(7).getStringCellValue());assertEquals(json.readTree(workbookRow.getCell(8).getStringCellValue()),json.readTree(records.get(1).get(8)));assertEquals(json.readTree(workbookRow.getCell(9).getStringCellValue()),json.readTree(records.get(1).get(9)));}
    }

    @Test void multiSridGeoPackageZipListsChecksummedMembersAndValidDatabases()throws Exception{
        call("deposit.create.class","Shapes",m("descriptors",List.of(m("name","Shape","type","DGeometry"))),token);call("deposit.create.object","Shapes",m("descriptors",m("Shape",ResourceAndGeometryIT.geometry("POINT (1 2)",4326L,2))),token);call("deposit.create.object","Shapes",m("descriptors",m("Shape",ResourceAndGeometryIT.geometry("POINT (3 4)",32633L,2))),token);
        var result=call("deposit.save.gpkg",m("query","SELECT Shapes.Shape"),m(),m("filename","split.gpkg","layer","shapes"),token).get("data");assertEquals("split.zip",result.get("filename").asString());assertEquals("application/zip",result.get("mediaType").asString());var files=result.get("files").asList(value->value.asMap(v->v.asObject()));assertEquals(2,files.size());var expected=new TreeMap<String,Map<String,Object>>();for(var file:files)expected.put((String)file.get("filename"),file);assertEquals(Set.of("split_32633.gpkg","split_4326.gpkg"),expected.keySet());
        byte[] archive=download(result.get("resourceId").asString(),result.get("bytes").asLong(),token);assertEquals(result.get("checksum").asString(),hash(archive));var seen=new TreeSet<String>();try(var zip=new ZipInputStream(new ByteArrayInputStream(archive))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){String name=entry.getName();assertTrue(seen.add(name),"Duplicate ZIP member "+name);byte[] content=zip.readAllBytes();var file=expected.get(name);assertNotNull(file,"Unexpected ZIP member "+name);assertEquals(((Number)file.get("bytes")).longValue(),content.length);assertEquals(file.get("checksum"),hash(content));java.nio.file.Path path=java.nio.file.Files.createTempFile("import-export-gpkg-member-",".gpkg");try{java.nio.file.Files.write(path,content);try(Connection db=DriverManager.getConnection("jdbc:sqlite:"+path);Statement sql=db.createStatement();ResultSet check=sql.executeQuery("PRAGMA integrity_check")){assertTrue(check.next());assertEquals("ok",check.getString(1));}try(Connection db=DriverManager.getConnection("jdbc:sqlite:"+path);Statement sql=db.createStatement();ResultSet srs=sql.executeQuery("SELECT srs_id FROM gpkg_contents WHERE table_name='shapes'")){assertTrue(srs.next());assertEquals(name.contains("32633")?32633:4326,srs.getInt(1));}}finally{java.nio.file.Files.deleteIfExists(path);}}}assertEquals(expected.keySet(),seen);
    }

    @Test void preparedSaveReplayReturnsOnePublishedResourceAndGrant(){
        call("deposit.create.class","Replay",m("descriptors",List.of(m("name","Code","type","String"))),token);String object=id(call("deposit.create.object","Replay",m("descriptors",m("Code","R-1")),token));String username="import-export-save-revision-"+UUID.randomUUID();String user=call("deposit.create.user",username,"typed-data-account-password",m(),token).get("data").get("id").asString();call("deposit.set.namespaceRole",m("id",user),"editor",token);String editor=call("deposit.utils.login",username,"typed-data-account-password").get("value").asString();call("deposit.set.activeNamespace",m("id",namespace),editor);
        var source=m("query","SELECT Replay.Code");var format=m("filename","replay.csv");String key=UUID.randomUUID().toString();String operation=call("deposit.action.prepare",key,"deposit.save.csv",List.of(source,m(),format),token).get("data").get("operationId").asString();
        var first=call("deposit.save.csv",source,m(),format,token).get("data");byte[] original=download(first.get("resourceId").asString(),first.get("bytes").asLong(),token);assertEquals("Replay.Code\r\nR-1\r\n",new String(original,java.nio.charset.StandardCharsets.UTF_8));call("deposit.set.descriptor",object,"Code","R-2",editor);token=call("deposit.utils.login","typed-data-admin","typed-data-account-password").get("value").asString();call("deposit.set.activeNamespace",m("id",namespace),token);call("deposit.action.resume",key,token);
        var replay=call("deposit.save.csv",source,m(),format,token).get("data");assertEquals(first.asMap(),replay.asMap());assertArrayEquals(original,download(replay.get("resourceId").asString(),replay.get("bytes").asLong(),token),"Prepared replay returns the original export without recollecting the changed query");String resource=first.get("resourceId").asString();
        String bindingActor;try(var session=driver.session()){bindingActor=session.run("MATCH (b:DepositOperationBinding {operationId:$operation}) RETURN b.actorId AS actor",m("operation",operation)).single().get("actor").asString();session.run("MATCH (b:DepositOperationBinding {actorId:$actor,operationId:$operation}) SET b.scope='server'",m("actor",bindingActor,"operation",operation)).consume();}
        var scopeFailure=assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,()->call("deposit.save.csv",source,m(),format,token));assertTrue(scopeFailure.getMessage().contains("SCOPE_MISMATCH"),scopeFailure.getMessage());
        try(var session=driver.session()){session.run("MATCH (b:DepositOperationBinding {actorId:$actor,operationId:$operation}) SET b.scope=$scope",m("actor",bindingActor,"operation",operation,"scope",namespace)).consume();}
        var hashFailure=assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,()->call("deposit.save.csv",source,m(),m("filename","changed.csv"),token));assertTrue(hashFailure.getMessage().contains("OPERATION_MISMATCH"),hashFailure.getMessage());
        String receiptActor;try(var session=driver.session()){receiptActor=session.run("MATCH (r:DepositReceipt {scope:$scope,operationId:$operation}) RETURN r.actorId AS actor",m("scope",namespace,"operation",operation)).single().get("actor").asString();session.run("MATCH (r:DepositReceipt {scope:$scope,operationId:$operation}) SET r.actorId=$actor",m("scope",namespace,"operation",operation,"actor",UUID.randomUUID().toString())).consume();}
        var explicitActorFailure=assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,()->call("deposit.save.csv",source,m(),format,token));assertTrue(explicitActorFailure.getMessage().contains("FORBIDDEN"),explicitActorFailure.getMessage());
        try(var session=driver.session()){session.run("MATCH (r:DepositReceipt {scope:$scope,operationId:$operation}) SET r.actorId=$actor",m("scope",namespace,"operation",operation,"actor",receiptActor)).consume();}
        try(var session=driver.session()){session.run("MATCH (b:DepositOperationBinding {actorId:$actor,operationId:$operation}) SET b.actorId=$other",m("actor",bindingActor,"operation",operation,"other",UUID.randomUUID().toString())).consume();}
        assertEquals(first.asMap(),call("deposit.save.csv",source,m(),format,token).get("data").asMap());
        try(var session=driver.session()){session.run("MATCH (r:DepositReceipt {scope:$scope,operationId:$operation}) SET r.actorId=$actor,r.requestHash='changed'",m("scope",namespace,"operation",operation,"actor",UUID.randomUUID().toString())).consume();}
        var actorFailure=assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,()->call("deposit.save.csv",source,m(),format,token));assertTrue(actorFailure.getMessage().contains("FORBIDDEN"),actorFailure.getMessage());
        try(var session=driver.session()){var counts=session.run("MATCH (r:DResource {id:$id}) OPTIONAL MATCH (g:DepositExportGrant {resourceId:$id}) OPTIONAL MATCH (receipt:DepositReceipt {scope:$scope,operationId:$operation}) RETURN count(DISTINCT r) AS resources,count(g) AS grants,count(DISTINCT receipt) AS receipts",m("id",resource,"scope",namespace,"operation",operation)).single();assertEquals(1L,counts.get("resources").asLong());assertEquals(1L,counts.get("grants").asLong());assertEquals(1L,counts.get("receipts").asLong());}call("deposit.action.release",token);
    }

    @Test void preparedLoadReplayReturnsTheSameStagedTableForEveryFormat()throws Exception{
        assertPreparedLoadReplay("deposit.load.csv",upload("code\r\nL-1\r\n".getBytes(java.nio.charset.StandardCharsets.UTF_8),"load-replay.csv",token),m(),true);
        byte[] workbook;try(Workbook output=new org.apache.poi.xssf.usermodel.XSSFWorkbook();var bytes=new java.io.ByteArrayOutputStream()){var sheet=output.createSheet("Data");sheet.createRow(0).createCell(0).setCellValue("code");sheet.createRow(1).createCell(0).setCellValue("X-1");output.write(bytes);workbook=bytes.toByteArray();}
        assertPreparedLoadReplay("deposit.load.xlsx",upload(workbook,"load-replay.xlsx",token),m("sheet","Data","headerRow",1L),false);
        Path fixture=Files.createTempFile("import-export-load-replay-",".gpkg");try{DataImportExportIT.createGeoPackageFixture(fixture);assertPreparedLoadReplay("deposit.load.gpkg",upload(Files.readAllBytes(fixture),"load-replay.gpkg",token),m("layer","specimens","geometryColumn","geom"),false);}finally{Files.deleteIfExists(fixture);}
    }

    @Test void rolledBackLoadLeavesNoPublishedTableLeaseReceiptOrStagingFiles(){
        String resource=upload("code\r\nROLLBACK-1\r\n".getBytes(java.nio.charset.StandardCharsets.UTF_8),"rollback-load.csv",token);String recovery=UUID.randomUUID().toString();var prepared=call("deposit.action.prepare",recovery,"deposit.load.csv",List.of(resource,m()),token).get("data");String operation=prepared.get("operationId").asString(),table=null,tablePath=null,indexPath=null;
        try(var session=driver.session();var tx=session.beginTransaction()){
            var loaded=tx.run("CYPHER 25 CALL deposit.load.csv($resource,$options,$token) YIELD data RETURN data",m("resource",resource,"options",m(),"token",token)).single().get("data");table=loaded.get("tableId").asString();var paths=tx.run("MATCH (t:DepositTabularTable {id:$id}) RETURN t.path AS path,t.rowIndexPath AS indexPath",m("id",table)).single();tablePath=paths.get("path").asString();indexPath=paths.get("indexPath").asString();assertTrue(Files.exists(ROOT.resolve("resources").resolve(tablePath)));assertTrue(Files.exists(ROOT.resolve("resources").resolve(indexPath)));tx.rollback();
        }
        assertNotNull(table);try(var session=driver.session()){
            assertEquals(0L,session.run("MATCH (t:DepositTabularTable {id:$id}) RETURN count(t) AS n",m("id",table)).single().get("n").asLong());assertEquals(0L,session.run("MATCH (l:DepositResourceLease {tableId:$id,type:'table'}) RETURN count(l) AS n",m("id",table)).single().get("n").asLong());assertEquals(0L,session.run("MATCH (r:DepositReceipt {scope:$ns,operationId:$operation}) RETURN count(r) AS n",m("ns",namespace,"operation",operation)).single().get("n").asLong());
        }
        assertFalse(Files.exists(ROOT.resolve("resources").resolve(tablePath)));assertFalse(Files.exists(ROOT.resolve("resources").resolve(indexPath)));call("deposit.action.release",token);
    }

    private void assertPreparedLoadReplay(String procedure,String resource,Map<String,Object> options,boolean expireBeforeReplay){
        if(expireBeforeReplay){String username="import-export-load-revision-"+UUID.randomUUID();String user=call("deposit.create.user",username,"typed-data-account-password",m(),token).get("data").get("id").asString();call("deposit.set.namespaceRole",m("id",user),"editor",token);String editor=call("deposit.utils.login",username,"typed-data-account-password").get("value").asString();call("deposit.set.activeNamespace",m("id",namespace),editor);call("deposit.create.class","LoadReplayRevision",m(),editor);call("deposit.set.activeNamespace",m("id",namespace),token);}
        long sequenceBefore;try(var session=driver.session()){sequenceBefore=session.run("MATCH (n:Namespace {id:$ns}) RETURN n.sequence AS n",m("ns",namespace)).single().get("n").asLong();}
        String recovery=UUID.randomUUID().toString();var prepared=call("deposit.action.prepare",recovery,procedure,List.of(resource,options),token).get("data");String operation=prepared.get("operationId").asString();var first=call(procedure,resource,options,token).get("data");String table=first.get("tableId").asString();
        try(var session=driver.session()){
            var counts=session.run("MATCH (t:DepositTabularTable {id:$id}) OPTIONAL MATCH (l:DepositResourceLease {tableId:$id,type:'table'}) OPTIONAL MATCH (r:DepositReceipt {scope:$ns,operationId:$operation}) RETURN count(DISTINCT t) AS tables,count(DISTINCT l) AS leases,count(DISTINCT r) AS receipts,t.path AS tablePath,t.rowIndexPath AS indexPath",m("id",table,"ns",namespace,"operation",operation)).single();assertEquals(1L,counts.get("tables").asLong());assertEquals(1L,counts.get("leases").asLong());assertEquals(1L,counts.get("receipts").asLong());assertFalse(counts.get("tablePath").asString().isBlank());assertFalse(counts.get("indexPath").asString().isBlank());assertTrue(Files.exists(ROOT.resolve("resources").resolve(counts.get("tablePath").asString())));assertTrue(Files.exists(ROOT.resolve("resources").resolve(counts.get("indexPath").asString())));
        }
        if(expireBeforeReplay){token=call("deposit.utils.login","typed-data-admin","typed-data-account-password").get("value").asString();call("deposit.set.activeNamespace",m("id",namespace),token);call("deposit.action.resume",recovery,token);}
        var replay=call(procedure,resource,options,token).get("data");assertEquals(first.asMap(),replay.asMap());
        if(expireBeforeReplay){var mismatch=assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,()->call(procedure,resource,m("headerRow",2L),token));assertTrue(mismatch.getMessage().contains("OPERATION_MISMATCH"),mismatch.getMessage());try(var session=driver.session()){session.run("MATCH (t:DepositTabularTable {id:$id}) SET t.expiresAt=0",m("id",table)).consume();}try{Thread.sleep(2_200);}catch(InterruptedException e){Thread.currentThread().interrupt();fail("Interrupted while waiting for table expiry");}try(var session=driver.session()){assertEquals(0L,session.run("MATCH (t:DepositTabularTable {id:$id}) RETURN count(t) AS n",m("id",table)).single().get("n").asLong());}assertEquals(first.asMap(),call(procedure,resource,options,token).get("data").asMap());try(var session=driver.session()){assertEquals(0L,session.run("MATCH (t:DepositTabularTable {id:$id}) RETURN count(t) AS n",m("id",table)).single().get("n").asLong(),"Receipt replay must not recreate or renew expired staging");}}
        if(expireBeforeReplay){
            try(var session=driver.session()){session.run("MATCH (b:DepositOperationBinding {operationId:$operation}) SET b.scope='server'",m("operation",operation)).consume();}
            var scopeFailure=assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,()->call(procedure,resource,options,token));assertTrue(scopeFailure.getMessage().contains("SCOPE_MISMATCH"),scopeFailure.getMessage());
            try(var session=driver.session()){session.run("MATCH (b:DepositOperationBinding {operationId:$operation}) SET b.scope=$scope",m("operation",operation,"scope",namespace)).consume();}
            String actor;try(var session=driver.session()){actor=session.run("MATCH (b:DepositOperationBinding {operationId:$operation}) RETURN b.actorId AS actor",m("operation",operation)).single().get("actor").asString();session.run("MATCH (b:DepositOperationBinding {actorId:$actor,operationId:$operation}) SET b.actorId=$other",m("actor",actor,"operation",operation,"other",UUID.randomUUID().toString())).consume();}
            assertEquals(first.asMap(),call(procedure,resource,options,token).get("data").asMap());
            String receiptActor;try(var session=driver.session()){receiptActor=session.run("MATCH (r:DepositReceipt {scope:$scope,operationId:$operation}) RETURN r.actorId AS actor",m("scope",namespace,"operation",operation)).single().get("actor").asString();session.run("MATCH (r:DepositReceipt {scope:$scope,operationId:$operation}) SET r.actorId=$actor",m("scope",namespace,"operation",operation,"actor",UUID.randomUUID().toString())).consume();}
            var explicitActorFailure=assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,()->call(procedure,resource,options,token));assertTrue(explicitActorFailure.getMessage().contains("FORBIDDEN"),explicitActorFailure.getMessage());
            try(var session=driver.session()){session.run("MATCH (r:DepositReceipt {scope:$scope,operationId:$operation}) SET r.actorId=$actor",m("scope",namespace,"operation",operation,"actor",receiptActor)).consume();}
            try(var session=driver.session()){session.run("MATCH (r:DepositReceipt {scope:$scope,operationId:$operation}) SET r.actorId=$actor,r.requestHash='changed'",m("scope",namespace,"operation",operation,"actor",UUID.randomUUID().toString())).consume();}
            var actorFailure=assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,()->call(procedure,resource,options,token));assertTrue(actorFailure.getMessage().contains("FORBIDDEN"),actorFailure.getMessage());
            try(var session=driver.session()){assertEquals(0L,session.run("MATCH (t:DepositTabularTable {id:$id}) RETURN count(t) AS n",m("id",table)).single().get("n").asLong(),"Actor rejection must not recreate expired staging");assertEquals(1L,session.run("MATCH (r:DepositReceipt {scope:$scope,operationId:$operation}) RETURN count(r) AS n",m("scope",namespace,"operation",operation)).single().get("n").asLong());}
        }
        try(var session=driver.session()){assertEquals(sequenceBefore,session.run("MATCH (n:Namespace {id:$ns}) RETURN n.sequence AS n",m("ns",namespace)).single().get("n").asLong());}
        call("deposit.action.release",token);
    }
}
